<?php
declare(strict_types=1);
namespace App\PackageModules\Payments;
use App\Platform\Contracts\PlatformRequestInterface;
use App\Platform\Package\AbstractPackageModule;
use App\Platform\Package\PlatformResponse;
use App\Platform\PlatformContext;
final class PaymentsModule extends AbstractPackageModule {
 public function name():string{return 'payments';} public function label():string{return 'Платежи';} public function priority():int{return 65;}
 public function adminNav():array{return [['group'=>'Коммерция','path'=>'/admin/payments','label'=>'Платежи','permission'=>'commerce.manage','icon'=>'credit-card']];}
 public function settingsSchema():array{return Providers\ProviderCatalog::settingsSchema();} public function settings():array{return Providers\ProviderCatalog::defaultSettings();}
 public function blocks():array{return [['type'=>'payment-checkout','label'=>'Форма оплаты','category'=>'commerce'],['type'=>'payment-methods','label'=>'Иконки оплаты','category'=>'commerce'],['type'=>'seller-info','label'=>'Реквизиты продавца','category'=>'commerce'],['type'=>'offer-document','label'=>'Документ оферты','category'=>'commerce']];}
 public function bootPlatform(PlatformContext $ctx):void { parent::bootPlatform($ctx); foreach(['api.routes','admin.pages','permissions.check','builder.widgets','events.publish','http.client'] as $cap)$ctx->capabilities()->require($cap); $ctx->events()->declare('payment.completed',['label'=>'Платёж завершён','category'=>'commerce','payload'=>['payment_id'=>'int','order_id'=>'int']]); $db=$ctx->database();$http=$ctx->http();$perms=$ctx->permissions();$svc=static fn()=>new PaymentService($db,$ctx->settings()->all(),$http,$ctx->config(),$http->apiPrefix(),$ctx->orders(),$ctx->catalog(),$ctx->events());$protected=[$http->authMiddleware(),$http->permissionMiddleware()];
 $http->get('/payments/config',static function()use($svc){PlatformResponse::json(['success'=>true,'data'=>$svc()->publicConfig()]);}); $http->get('/commerce/catalog',static function()use($db,$ctx){PlatformResponse::json(['success'=>true,'data'=>(new CommerceCatalog($db,$ctx->catalog()))->listPurchasable()]);}); $http->get('/commerce/item',static function(PlatformRequestInterface $r)use($db,$ctx){$q=$r->query();$item=(new CommerceCatalog($db,$ctx->catalog()))->peek((string)($q['type']??''),(int)($q['id']??0));if(!$item)PlatformResponse::error('Not found',404);PlatformResponse::json(['success'=>true,'data'=>$item]);}); $http->post('/payments/checkout',static function(PlatformRequestInterface $r)use($svc){PlatformResponse::json(['success'=>true,'data'=>$svc()->checkout($r->body())]);},[$http->rateLimitMiddleware(20,60)]); $http->get('/payments/status/{id}',static function(PlatformRequestInterface $r,string $id)use($svc){$row=$svc()->paymentStatus((int)$id);if(!$row)PlatformResponse::error('Not found',404);PlatformResponse::json(['success'=>true,'data'=>$row]);}); $http->post('/payments/webhook',static function(PlatformRequestInterface $r)use($svc){$ack=$svc()->handleWebhook($r);PlatformResponse::json(is_string($ack)?['ack'=>$ack]:$ack);},[$http->rateLimitMiddleware(60,60)]); $http->get('/admin/payments',static function(PlatformRequestInterface $r)use($db,$perms){$perms->require($r->user()??[],'commerce.manage');PlatformResponse::json(['data'=>$db->all('SELECT * FROM payments ORDER BY id DESC LIMIT 300')]);},$protected); $http->get('/admin/payments/{id}',static function(PlatformRequestInterface $r,string $id)use($db,$perms){$perms->require($r->user()??[],'commerce.manage');$row=$db->one('SELECT * FROM payments WHERE id=?',[(int)$id]);if(!$row)PlatformResponse::error('Not found',404);PlatformResponse::json(['data'=>$row]);},$protected); }
}